//! Build script of the checker. It plays the part of a crate that depends on
//! `fletch-sys` and needs the C header, for example to compile C code of its
//! own against it. Do not edit this file.

use std::env;
use std::path::PathBuf;

fn main() {
    println!("cargo::rerun-if-changed=build.rs");
    println!("cargo::rerun-if-env-changed=DEP_FLETCH_INCLUDE");

    let Some(include) = env::var_os("DEP_FLETCH_INCLUDE") else {
        panic!(
            "\n\nDEP_FLETCH_INCLUDE is not set. Cargo sets it for this build script when \
             both of these are true:\n  \
             1. fletch-sys/Cargo.toml has `links = \"fletch\"` in [package];\n  \
             2. fletch-sys/build.rs prints `cargo::metadata=include=<directory>`.\n"
        );
    };
    let header = PathBuf::from(&include).join("fletch.h");
    assert!(
        header.is_file(),
        "\n\nDEP_FLETCH_INCLUDE is `{}`, but there is no fletch.h in that directory. \
         Print the absolute path of vendor/fletch/include.\n",
        PathBuf::from(&include).display()
    );
    println!(
        "cargo::rustc-env=CHECKER_FLETCH_HEADER={}",
        header.display()
    );
}
